'use client';

import { UsersIcon } from 'lucide-react';

import { USERS_FEATURE_PACK } from '../../../feature-packs';
import { createConstructiveUsersAdapter } from '../../console-kit/constructive/users-adapter';
import type { ConstructiveCapabilityContribution } from '../../console-kit/constructive/constructive-capabilities';
import type {
  ConsoleKitFeatureComponentProps,
  ConsoleKitFeatureModule
} from '../../console-kit/feature-module';
import {
  UsersFeaturePack,
  type UsersSection,
  type UsersFeaturePackProps
} from './users-feature-pack';

export const usersCapabilityDiscovery = {
  rules: [
    { capability: 'users.directory', endpoint: 'auth', operation: 'query', fields: ['users'] },
    { capability: 'users.memberships', endpoint: 'admin', operation: 'query', fields: ['appMemberships'] },
    { capability: 'users.capabilities', endpoint: 'admin', operation: 'query', fields: ['appCapabilities'] },
    { capability: 'users.profiles', endpoint: 'admin', operation: 'query', fields: ['appProfiles'] },
    { capability: 'users.invites', endpoint: 'admin', operation: 'query', fields: ['appInvites'] }
  ]
} satisfies ConstructiveCapabilityContribution;

function sectionForRoute(
  route: ConsoleKitFeatureComponentProps['route']
): UsersSection {
  if (route.feature !== 'users') return 'members';
  switch (route.screen) {
    case 'member':
      return 'members';
    case 'invitation':
      return 'invitations';
    case 'profile':
      return 'profiles';
    default:
      return route.screen;
  }
}

function UsersConsoleFeature({
  adapterProps,
  onError,
  onRouteChange,
  route
}: ConsoleKitFeatureComponentProps) {
  const appAccessRoute = route.feature === 'users' ? route : undefined;

  return (
    <UsersFeaturePack
      {...(adapterProps as UsersFeaturePackProps)}
      focusedInvitationId={appAccessRoute?.screen === 'invitation'
        ? appAccessRoute.invitationId
        : undefined}
      focusedMemberId={appAccessRoute?.screen === 'member'
        ? appAccessRoute.membershipId
        : undefined}
      focusedProfileId={appAccessRoute?.screen === 'profile'
        ? appAccessRoute.profileId
        : undefined}
      onError={onError}
      onSectionChange={(nextSection) => onRouteChange({
        feature: 'users',
        screen: nextSection
      })}
      section={sectionForRoute(route)}
    />
  );
}

export const usersConsoleModule = {
  id: 'users',
  manifest: USERS_FEATURE_PACK,
  icon: UsersIcon,
  Component: UsersConsoleFeature,
  capabilityDiscovery: usersCapabilityDiscovery,
  createAdapter: ({ store, discovery }) =>
    createConstructiveUsersAdapter({ store, discovery })
} satisfies ConsoleKitFeatureModule;

import type { AtomicCapabilityId } from '../../../feature-packs';
import type { UsersFeaturePackProps } from '../../feature-packs/users/users-feature-pack';
import { loadScopeAccess } from '../../scope-access/scope-access-load';
import { scopeAccessView } from '../../scope-access/scope-access-view';
import { scopeNames } from '../../scope-access/scope-names';
import type { ConsoleKitFeatureAdapter } from '../console-kit-contracts';
import type { ConsoleKitStoreApi } from '../store';
import type { ConstructiveCapabilityDiscovery } from './constructive-capabilities';
import { notifyConsoleAdapters, packAvailability } from './constructive-adapter-utils';

export type ConstructiveUsersAdapterOptions = Readonly<{
  store: ConsoleKitStoreApi;
  discovery: ConstructiveCapabilityDiscovery;
}>;

const APP = { names: scopeNames('app') };

/**
 * App access in Console Kit: the scope-access core on the `app` scope, with
 * Console Kit's discovery for the schemas and its store for reloads.
 */
export function createConstructiveUsersAdapter(
  options: ConstructiveUsersAdapterOptions
): ConsoleKitFeatureAdapter<UsersFeaturePackProps> {
  const capabilities: readonly AtomicCapabilityId[] = [
    'users.directory',
    'users.memberships',
    'users.capabilities',
    'users.profiles',
    'users.invites'
  ];

  return {
    capabilities,
    requiresCapabilityDiscovery: true,
    getAvailability: () => packAvailability(options.store, 'users'),
    subscribe(runtime, listener) {
      const unsubscribe = options.discovery.subscribe(listener);
      void options.discovery.ensure(runtime);
      return unsubscribe;
    },
    async load(runtime, signal) {
      const schemas = options.discovery.getSchemas();
      const directory = await loadScopeAccess(runtime, schemas, APP, signal);
      return scopeAccessView(runtime, schemas, APP, directory, () => notifyConsoleAdapters(options.store));
    }
  };
}
